double exponential_random(double lambda, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    // Generate uniform random using LCG
    unsigned int new_seed = (a * seed + c) % m;
    seed = new_seed;

    // Convert to double in (0,1] range
    double u = static_cast<double>(new_seed) / m;

    // Avoid u=0 which would cause log(0)
    if (u == 0.0) u = 1e-10;

    // Inverse transform for exponential distribution
    return -std::log(u) / lambda;
}

